import{_ as t,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"List Roles","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"List Roles","description":"Paginated list of every admin role configured in the store.","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/roles?per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"name\\": \\"Administrator\\",\\n      \\"description\\": \\"Administrator role\\",\\n      \\"permissionType\\": \\"all\\",\\n      \\"permissions\\": null,\\n      \\"createdAt\\": null,\\n      \\"updatedAt\\": null\\n    },\\n    {\\n      \\"id\\": 3,\\n      \\"name\\": \\"Catalogue manager\\",\\n      \\"description\\": \\"This is catalogue manager and permissions are added accordingly\\",\\n      \\"permissionType\\": \\"custom\\",\\n      \\"permissions\\": [\\n        \\"catalog\\",\\n        \\"catalog.products\\",\\n        \\"catalog.products.create\\",\\n        \\"catalog.products.edit\\"\\n      ],\\n      \\"createdAt\\": \\"2026-05-13T18:30:58+05:30\\",\\n      \\"updatedAt\\": \\"2026-05-13T18:30:58+05:30\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 2,\\n    \\"from\\": 1,\\n    \\"to\\": 2\\n  }\\n}\\n"},{"id":"filtered","title":"Filtered + Sorted","description":"Narrow by name and permission type, sorted by name ascending. Supplying multiple filters narrows the result (logical AND).","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/roles?name=Catalog&permission_type=custom&sort=name&order=asc&per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 3,\\n      \\"name\\": \\"Catalogue manager\\",\\n      \\"description\\": \\"This is catalogue manager and permissions are added accordingly\\",\\n      \\"permissionType\\": \\"custom\\",\\n      \\"permissions\\": [\\n        \\"catalog\\",\\n        \\"catalog.products\\",\\n        \\"catalog.products.create\\",\\n        \\"catalog.products.edit\\"\\n      ],\\n      \\"createdAt\\": \\"2026-05-13T18:30:58+05:30\\",\\n      \\"updatedAt\\": \\"2026-05-13T18:30:58+05:30\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/settings/roles/list.md","filePath":"api/rest-api/admin/settings/roles/list.md","lastUpdated":1783420618000}'),d={name:"api/rest-api/admin/settings/roles/list.md"};function n(i,e,s,l,c,p){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="list-roles" tabindex="-1">List Roles <a class="header-anchor" href="#list-roles" aria-label="Permalink to &quot;List Roles&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/settings/roles</code></td><td>GET</td></tr></tbody></table><p>Returns every admin role configured in the store in the <code>{ data, meta }</code> envelope. A role is a named permission set assigned to admin users to control which areas of the admin panel they can access. Use it to populate a role picker, audit which roles exist, or look up a role&#39;s <code>id</code> before a detail / update / delete call.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>Page number, 1-based. Default <code>1</code>.</td></tr><tr><td><code>per_page</code></td><td>Items per page. Default <code>10</code>, max <code>50</code>.</td></tr></tbody></table><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Query parameters that narrow the result. Supplying more than one <strong>narrows further</strong> — they combine with logical <strong>AND</strong>. They mirror the admin Roles datagrid filters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Match</th><th>Example</th></tr></thead><tbody><tr><td><code>name</code></td><td>Partial (contains).</td><td><code>?name=Catalog</code></td></tr><tr><td><code>permission_type</code></td><td>Exact — <code>all</code> or <code>custom</code>.</td><td><code>?permission_type=custom</code></td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>id</code> (default), <code>name</code></td></tr><tr><td><code>order</code></td><td><code>asc</code>, <code>desc</code> (default <code>desc</code>)</td></tr></tbody></table><p>Both the compound form <code>?sort=name-asc</code> and the split form <code>?sort=name&amp;order=asc</code> are accepted.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>permissions</code> is a string array of permission keys for a <code>custom</code> role. For an <code>all</code> role it is <code>null</code> (full access — no explicit key list is stored).</li><li>Seeded core roles (such as Administrator) may have <code>null</code> <code>createdAt</code> / <code>updatedAt</code>.</li></ul><p>See the <a href="./">Roles overview</a> for field meanings and behaviour.</p>',14)]))}const u=t(d,[["render",n]]);export{h as __pageData,u as default};
